const url = require('url');
const REPO = $env.REPO_DIR || '/home/node/repo';
const L = await import(url.pathToFileURL(REPO + '/automation/lib/w05.mjs').href);
const j = $input.first().json;
const src = j.f ? j : ($('After event (w05.finish)').isExecuted ? $('After event (w05.finish)').first().json : j);
return [{ json: { lane: src.lane, status: src.status || 200, body: src.body || {}, wa: src.wa || null, to: 'lead', lead_id: src.lead_id || (src.ctx && src.ctx.lead && src.ctx.lead.id) || null, f: src.f || null } }];

const url = require('url');
const REPO = $env.REPO_DIR || '/home/node/repo';
const L = await import(url.pathToFileURL(REPO + '/automation/lib/w05.mjs').href);
const j = $input.first().json;
const out = [];
if (j.wa) out.push({ kind: 'wa', to: 'lead', lead_id: j.lead_id, wa: j.wa });
const f = j.f; if (!f) return out.map((x) => ({ json: x }));
if (f.invite) out.push({ kind: 'mail', mail: { message: f.invite.message, saveToSentItems: true } });
if (f.broker.email) out.push({ kind: 'mail', mail: { message: { subject: f.broker.email.subject, body: { contentType: 'Text', content: f.broker.email.body }, toRecipients: [{ emailAddress: { address: f.broker.email.to } }] }, saveToSentItems: true } });
if (f.broker.wa) out.push({ kind: 'wa', to: 'broker', lead_id: j.lead_id, wa: f.broker.wa });
if (f.lead_wa) out.push({ kind: 'wa', to: 'lead', lead_id: j.lead_id, wa: f.lead_wa });
for (const k of ['w06', 'w09', 'w07', 'capi', 'ask_email', 'alert']) if (f[k]) out.push({ kind: k, ...f[k] });
return out.map((x) => ({ json: x }));

const url = require('url');
const REPO = $env.REPO_DIR || '/home/node/repo';
